#[derive(Clone, Debug, PartialEq)]
enum Op { Get(String), Put(String, i64), Log(String) }

fn run(op: &Op, store: &mut Store) -> Result<i64, StoreError> {
    match op {
        Op::Get(k)    => store.read(k),
        Op::Put(k, v) => store.write(k, *v),
        Op::Log(m)    => { store.log(m); Ok(0) }
    }   // a new variant breaks every interpreter here
}
